import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { transformSync } from "esbuild";
import { appRuntimePaths } from "./runtime-manifest.mjs";
import { styleRuntimePaths } from "./style-manifest.mjs";

const root = dirname(dirname(fileURLToPath(import.meta.url)));

// Canonical tesseract.js worker patch. tesseract.js@7's worker file
// uses `require('..')` which trips Node's CJS resolver in certain
// pkg-packaged FS layouts; the fix is the explicit `../index.js`
// path. This patch lives here (build-time only) so the patched file
// is captured in the pkg snapshot. Do NOT add a runtime copy of this
// patch in the server; pkg's virtual FS is read-only at runtime,
// and the build-time patch already covers both dev and packaged
// flows because `npm start` runs build:app via prestart.
try {
  const workerFile = join(root, "node_modules", "tesseract.js", "src", "worker-script", "node", "index.js");
  const content = readFileSync(workerFile, "utf8");
  if (content.includes("require('..')")) {
    writeFileSync(workerFile, content.replace("require('..')", "require('../index.js')"), "utf8");
  }
} catch (err) {}
const cssBundlePath = "styles.bundle.css";

const banner = [
  "// Generated by scripts/build-app-bundle.mjs.",
  "// Keep source edits in app/ modules or app.js, then run npm run build:app.",
  "",
].join("\n");

function stripJsSourceMapComments(source) {
  return source.replace(/(?:^|\n)\/\/# sourceMappingURL=.*(?:\n|$)/g, "\n").trimEnd();
}

function compactJsLeadingWhitespace(source) {
  let output = "";
  let quote = "";
  let escaped = false;
  let lineStart = true;
  let pendingBlankLine = false;
  let inRegex = false;

  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    const next = source[index + 1];

    if (quote) {
      output += char;
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === quote) {
        quote = "";
      }
      lineStart = char === "\n";
      continue;
    }

    if (inRegex) {
      output += char;
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === "/") {
        inRegex = false;
      }
      lineStart = char === "\n";
      continue;
    }

    if (char === "\"" || char === "'" || char === "`") {
      if (pendingBlankLine && output && !output.endsWith("\n")) output += "\n";
      pendingBlankLine = false;
      quote = char;
      output += char;
      lineStart = false;
      continue;
    }

    if (char === "/" && next === "/") {
      if (source.startsWith("// =====", index)) {
        let lineEnd = index;
        while (lineEnd < source.length && source[lineEnd] !== "\n") {
          lineEnd += 1;
        }
        output += source.slice(index, lineEnd);
        index = lineEnd - 1;
        lineStart = false;
        continue;
      }
      index += 1;
      while (index < source.length && source[index] !== "\n") {
        index += 1;
      }
      index -= 1;
      continue;
    }

    if (char === "/" && next === "*") {
      index += 2;
      while (index < source.length && !(source[index] === "*" && source[index + 1] === "/")) {
        index += 1;
      }
      index += 1;
      continue;
    }

    if (char === "/") {
      const prevText = output.trimEnd();
      const lastChar = prevText.at(-1);
      const isRegexStart = !lastChar || "=,;:?&|!([{~^+-*/%<>".includes(lastChar) || 
        /\b(return|yield|delete|typeof|void|throw|await|typeof|instanceof|in|do|else|case)$/.test(prevText);
      if (isRegexStart) {
        inRegex = true;
        output += char;
        lineStart = false;
        continue;
      }
    }

    if (char === "\n") {
      if (!lineStart) output += "\n";
      else pendingBlankLine = true;
      lineStart = true;
      continue;
    }

    if (lineStart && (char === " " || char === "\t")) continue;

    if (pendingBlankLine && output && !output.endsWith("\n")) output += "\n";
    pendingBlankLine = false;
    output += char;
    lineStart = false;
  }

  return output.trimEnd();
}

const body = appRuntimePaths
  .map((path) => [
    `// ===== ${path} =====`,
    stripJsSourceMapComments(readFileSync(join(root, path), "utf8")),
    "",
  ].join("\n"))
  .join("\n");

const appBundlePath = join(root, "app.bundle.js");
const minifiedBody = transformSync(compactJsLeadingWhitespace(body), {
  charset: "utf8",
  legalComments: "none",
  loader: "js",
  minifyIdentifiers: false,
  minifySyntax: false,
  minifyWhitespace: true,
  target: "esnext",
}).code.trim();
const sourceSectionManifest = appRuntimePaths
  .map((path) => `// Source section: ${path}`)
  .join("\n");
writeFileSync(appBundlePath, `${banner}${sourceSectionManifest}\n${minifiedBody}\n`, "utf8");

const syntaxCheck = spawnSync(process.execPath, ["--check", appBundlePath], {
  cwd: root,
  encoding: "utf8",
});
if (syntaxCheck.status !== 0) {
  console.error(syntaxCheck.stderr || syntaxCheck.stdout);
  process.exit(syntaxCheck.status || 1);
}

console.log(`Built app.bundle.js from ${appRuntimePaths.length} source files.`);

function stripCssComments(source) {
  let output = "";
  let quote = "";
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    const next = source[index + 1];

    if (quote) {
      output += char;
      if (char === "\\") {
        output += next || "";
        index += 1;
      } else if (char === quote) {
        quote = "";
      }
      continue;
    }

    if (char === "\"" || char === "'") {
      quote = char;
      output += char;
      continue;
    }

    if (char === "/" && next === "*") {
      index += 2;
      while (index < source.length && !(source[index] === "*" && source[index + 1] === "/")) index += 1;
      index += 1;
      continue;
    }

    output += char;
  }
  return output;
}

function minifyCss(source) {
  const withoutComments = stripCssComments(source);
  let output = "";
  let quote = "";
  let pendingSpace = false;
  const tightBefore = new Set("{}:;,>+~)]=");
  const tightAfter = new Set("{}:;,>+~([=");
  // Stack of open parens; each entry is true when that paren (or an ancestor)
  // is inside a CSS math function. Inside math context, `+`/`-` are arithmetic
  // operators that REQUIRE surrounding whitespace, so they must not be tightened
  // like the adjacent-sibling/`+` selector combinator. `-`/`*`/`/` are never in
  // the tight sets, so only `+` needs the guard, but we keep the context general.
  const mathFn = /(?:^|[^\w-])(?:calc|min|max|clamp)$/i;
  const parenStack = [];
  const inMath = () => parenStack.length > 0 && parenStack[parenStack.length - 1];
  const needsPreludeSpaceBeforeParen = () => {
    if (!pendingSpace) return false;
    if (/(?:^|[^\w-])(?:and|or|not)$/i.test(output)) return true;
    const blockStart = Math.max(output.lastIndexOf("{"), output.lastIndexOf("}"));
    const prelude = output.slice(blockStart + 1);
    return /^@container\s+(?!style$)[a-z_][\w-]*$/i.test(prelude);
  };
  // A `+` directly after the previous token normally suppresses the following
  // space (selector combinator), but inside a math function the trailing space
  // must survive too.
  const suppressLeadingSpace = (prev) => tightAfter.has(prev) && !(prev === "+" && inMath());

  for (let index = 0; index < withoutComments.length; index += 1) {
    const char = withoutComments[index];

    if (quote) {
      output += char;
      if (char === "\\") {
        output += withoutComments[index + 1] || "";
        index += 1;
      } else if (char === quote) {
        quote = "";
      }
      continue;
    }

    if (char === "\"" || char === "'") {
      if (pendingSpace && output && !suppressLeadingSpace(output.at(-1))) output += " ";
      pendingSpace = false;
      quote = char;
      output += char;
      continue;
    }

    if (/\s/.test(char)) {
      pendingSpace = true;
      continue;
    }

    if (char === "(") {
      const parentMath = inMath();
      const startsMathFn = mathFn.test(output.slice(-10));
      // Outside math, `(` tightens the preceding token. Inside math the space
      // can be a required operator gap (e.g. `25px + (…)`), so preserve it.
      if (parentMath || needsPreludeSpaceBeforeParen()) {
        if (pendingSpace && output && !suppressLeadingSpace(output.at(-1))) output += " ";
      } else {
        output = output.trimEnd();
      }
      output += char;
      pendingSpace = false;
      parenStack.push(parentMath || startsMathFn);
      continue;
    }

    if (char === ")") {
      output = output.trimEnd();
      output += char;
      pendingSpace = false;
      parenStack.pop();
      continue;
    }

    // Inside a math function, `+` is an arithmetic operator needing whitespace;
    // treat it as a normal token so the surrounding spaces are preserved.
    const tightenBefore = tightBefore.has(char) && !(char === "+" && inMath());
    if (tightenBefore) output = output.trimEnd();
    else if (pendingSpace && output && !suppressLeadingSpace(output.at(-1))) output += " ";

    output += char;
    pendingSpace = false;
  }

  return output.trim();
}

const cssSource = styleRuntimePaths
  .map((path) => readFileSync(join(root, path), "utf8"))
  .join("\n");
const cssBundle = minifyCss(cssSource);
writeFileSync(join(root, cssBundlePath), `${cssBundle}\n`, "utf8");
console.log(`Built ${cssBundlePath} from ${styleRuntimePaths.length} source files.`);
